  private evaluate(sender: string, rid: string): null {
    const r = this.receipts.get(rid);
    if (!r) this.fail("[EXPECTED]", "receipt not found");
    const j = this.jobs.get(r!.jobId);
    if (!j) this.fail("[EXPECTED]", "job not found");
    if (sender !== j!.client && sender !== j!.worker) this.fail("[EXPECTED]", "only the client or the worker can request an evaluation");
    if (r!.status !== "PENDING") this.fail("[EXPECTED]", "receipt is not pending evaluation");
    if (j!.status !== "IN_PROGRESS") this.fail("[EXPECTED]", "job is not in progress");
    if (this.unreachable && this.unreachable.test(r!.url)) this.fail("[EXTERNAL]", "web request failed");
    const ev = this.evaluator(r!.url, j!.criteria.length);
    const results = j!.criteria.map((c, i) => {
      const status = ev.statuses[i]!;
      return {
        criterion_id: c.id, status, reason_code: REASON_FOR_STATUS[status],
        evidence_excerpt: status === "UNVERIFIABLE" ? "" : status === "NOT_MET" ? "" : `quoted evidence for ${c.id}`,
      };
    });
    r!.status = "EVALUATED";
    r!.requestedBy = sender;
    r!.evidenceHash = ev.evidenceHash;
    r!.evidenceSize = ev.evidenceSize;
    r!.overall = deriveOverall(ev.statuses);
    r!.results = results;
    j!.status = r!.overall;
    return null;
  }

